<?php use SwimlogStandalone\WorkoutDetails as WD;$ef=$eventForm;$v=$ef['values'];$op=$ef['operation']; ?>
<section class="calendar-panel workout-page" aria-labelledby="event-form-title"><div class="workout-page-heading"><h2 id="event-form-title"><?php echo $op==='result'?'Record race result':($ef['id']==='new'?'Add event':'Edit event'); ?></h2><a class="control" href="<?php echo esc_url($ef['context']['url']); ?>">Back to calendar</a></div>
<?php if($op==='result'): ?><h3><?php echo esc_html($ef['prior']->event_name); ?></h3><p><?php echo esc_html($ef['prior']->event_date.' · '.$ef['prior']->distance_value.' '.$ef['prior']->course_unit.' · '.WD::stroke($ef['prior']->stroke)); ?></p><?php endif; ?>
<?php if($ef['error']): ?><p role="alert"><?php echo esc_html($ef['error']->get_error_message()); ?></p><p><a href="<?php echo esc_url($ef['context']['url'].($op==='result'?'&event_result=':'&edit_event=').$ef['id']); ?>">Reload event form</a></p><?php endif; ?>
<form class="event-editor plan-editor" method="post" action="/?action=event_save"><?php foreach(array('event_id'=>$ef['id'],'operation'=>$op,'nonce'=>wp_create_nonce('swimlog_event_'.$op.'_'.$ef['id']),'revision'=>$ef['revision'],'date'=>$ef['context']['date'],'view'=>$ef['context']['view'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?>
<?php if($op==='edit'): ?>
<div class="plan-field plan-wide"><label for="event-name">Event name</label><input id="event-name" name="event_name" maxlength="191" required value="<?php echo esc_attr($v['event_name']); ?>"></div>
<div class="plan-field"><label for="event-date">Event date</label><input id="event-date" name="event_date" type="date" min="1900-01-01" max="2199-12-31" required value="<?php echo esc_attr($v['event_date']); ?>"><small>Upcoming and historical events are supported.</small></div>
<div class="plan-field"><label for="event-time">Start time (optional)</label><input id="event-time" name="event_time" type="time" step="60" value="<?php echo esc_attr($v['event_time']); ?>"></div>
<div class="plan-field"><label for="event-distance">Event distance</label><select id="event-distance" name="distance_value"><?php foreach($ef['distances']as$distance): ?><option value="<?php echo esc_attr($distance); ?>" <?php selected($v['distance_value'],(string)$distance); ?>><?php echo esc_html($distance); ?></option><?php endforeach; ?></select></div>
<div class="plan-field"><label for="event-course">Event course</label><select id="event-course" name="course_unit"><?php foreach(array('m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($v['course_unit'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>
<div class="plan-field"><label for="event-stroke">Event stroke</label><select id="event-stroke" name="stroke"><?php foreach($ef['strokes']as$stroke): ?><option value="<?php echo esc_attr($stroke); ?>" <?php selected($v['stroke'],$stroke); ?>><?php echo esc_html(WD::stroke($stroke)); ?></option><?php endforeach; ?></select></div>
<div class="plan-field"><label for="event-location">Event location</label><select id="event-location" name="location_id"><option value="0">No location</option><?php foreach($ef['locations']as$location): ?><option value="<?php echo esc_attr($location['id']); ?>" <?php selected($v['location_id'],(string)$location['id']); ?>><?php echo esc_html($location['name']); ?></option><?php endforeach; ?></select></div>
<?php else: ?>
<div class="plan-field"><label for="race-time">Race time (optional)</label><input id="race-time" name="result_time" aria-describedby="race-time-help" placeholder="1:23.456" value="<?php echo esc_attr($v['result_time']); ?>"><small id="race-time-help">M:SS or H:MM:SS; up to three fractional-second digits.</small></div>
<div class="plan-field"><label for="race-placement">Placement (optional)</label><input id="race-placement" name="placement" type="number" min="1" max="100000" step="1" value="<?php echo esc_attr($v['placement']); ?>"></div>
<?php if(($ef['prior']->result_time_ms??null)!==null||($ef['prior']->placement??null)!==null): ?><label class="event-clear plan-wide"><input type="checkbox" name="clear_result" value="1" <?php checked($v['clear_result'],'1'); ?>> Allow clearing an existing race time or placement</label><?php endif; ?>
<?php endif; ?>
<div class="plan-field plan-wide"><label for="event-notes">Event notes (optional)</label><textarea id="event-notes" name="notes" rows="6" maxlength="60000"><?php echo esc_textarea($v['notes']); ?></textarea><small>These are the event’s shared notes, also shown with its race result.</small></div>
<div class="plan-actions plan-wide"><button><?php echo $op==='result'?'Save race result':'Save event'; ?></button><a class="control" href="<?php echo esc_url($ef['context']['url']); ?>">Cancel</a></div></form></section>
